const VALIDATORS = {
  fFirst: v => v.trim().length >= 2,
  fLast:  v => v.trim().length >= 2,
  fEmail: v => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()),
  fPhone: v => /^[\d+\-\s()]{9,15}$/.test(v.trim())
};

function submitForm(){
  let ok = true;
  Object.keys(VALIDATORS).forEach(wrapId=>{ if (!validateField(wrapId)) ok = false; });
  const tgConsent = document.getElementById('inTgConsent');
  document.getElementById('tgConsentWrap').classList.toggle('invalid', !tgConsent.checked);
  if (!tgConsent.checked) ok = false;
  const consent = document.getElementById('inConsent');
  document.getElementById('consentWrap').classList.toggle('invalid', !consent.checked);
  if (!consent.checked) ok = false;
  if (!ok){
    const firstInvalid = document.querySelector('.field.invalid input');
    if (firstInvalid) firstInvalid.focus();
    return;
  }
  userName = document.getElementById('inFirst').value.trim();
  ctaBtn.disabled = true;
  ctaBtn.textContent = T().submitting;
  const first = userName;
  const last = (document.getElementById('inLast').value||'').trim();
  const payload = {
    name: (first + ' ' + last).trim(),
    email: (document.getElementById('inEmail').value||'').trim(),
    phone: (document.getElementById('inPhone').value||'').trim(),
    lang: lang,
    src: computeSrc()
  };
  if (window.__trk) window.__trk.ev('register_submit', true);
  const FALLBACK = 'https://telegram.me/joni_agent_bot';
  // same-tab redirect (mobile Safari blocks window.open outside a direct tap)
  fetch('https://nanohubdemo.vercel.app/api/register', {
    method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(payload)
  })
